3	import { createClient } from "@/lib/supabase/server";
4	import { signItemImages, displayPath } from "@/lib/storage/signed";
5	import { fetchForecast } from "@/lib/weather/open-meteo";
6	import { laterAdvice } from "@/lib/weather/advice";
7	import { personalBand, applyFormalityOverride } from "@/lib/generator/rules";
8	import { buildCandidates, missingCategory, type CandidateItem } from "@/lib/generator/candidates";
9	import { rankTopN } from "@/lib/generator/rank";
10	import { rerank } from "@/lib/generator/rerank";
11	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
12	import {
13	  resolveLocation,
14	  roundCoord,
15	  LocationInputSchema,
16	  type LocationSource,
17	} from "@/lib/weather/location";
18	import type {
19	  GenerateResult,
20	  Look,
21	  LookPiece,
22	  UiOccasion,
23	  WeatherPayload,
24	} from "@/lib/generator/types";
25	
26	function currentSeason(d: Date): string {
27	  const m = d.getMonth();
28	  return m < 2 || m === 11 ? "Winter" : m < 5 ? "Spring" : m < 8 ? "Summer" : "Autumn";
29	}
30	
31	export async function generate(input: {
32	  occasion: UiOccasion;
33	  formality: number | null;
34	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
35	  lean: string[];
36	  city?: { lat: number; lon: number; label: string; source: LocationSource };
37	}): Promise<GenerateResult> {
38	  try {
39	    const supabase = await createClient();
40	    const {
41	      data: { user },
42	    } = await supabase.auth.getUser();
43	    if (!user) return { status: "error", message: "Not signed in" };
44	
45	    const { data: profile } = await supabase
46	      .from("profiles")
47	      .select(
48	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source",
49	      )
50	      .eq("id", user.id)
51	      .single();
52	    const { data: itemsRaw } = await supabase
53	      .from("items")
54	      .select("*")
55	      .eq("user_id", user.id)
56	      .eq("archived", false);
57	    const items = itemsRaw ?? [];
58	    const byId = new Map(items.map((i) => [i.id, i]));
59	
60	    const loc = resolveLocation({ input: input.city, profile });
61	
62	    const now = new Date();
63	    const f = await fetchForecast(loc.lat, loc.lon);
64	    const advice = laterAdvice(f.hourly);
65	    const weather: WeatherPayload = {
66	      tempC: f.tempC,
67	      feelsLikeC: f.feelsLikeC,
68	      condition: f.condition,
69	      cityLabel: loc.label,
70	      timezone: f.timezone,
71	      locationOrigin: loc.origin,
72	      laterSentence: advice.sentence,
73	      adviceClause: advice.adviceClause,
74	      laterLabel: "Later",
75	      hourly: f.hourly,
76	    };
77	
78	    const candItems: CandidateItem[] = items.map((i) => ({
79	      id: i.id,
80	      category: i.category,
81	      colors: i.colors ?? [],
82	      formality: i.formality,
83	      seasons: i.seasons ?? [],
84	      material: i.material,
85	    }));
86	    // Occasion gives the context; the user's onboarding dress codes narrow it;
87	    // an explicit Refine formality overrides both.
88	    const band = applyFormalityOverride(
89	      personalBand(input.occasion, profile),
90	      input.formality,
91	    );
92	    const candidateArgs = {
93	      band,
94	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
95	      season: currentSeason(now),
96	      excludeItemIds: [],
97	      maxAccessories: 1,
98	    };
99	    const combos = buildCandidates(candItems, candidateArgs);
100	    if (combos.length === 0) {
101	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
102	    }
103	
104	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
105	    // The Refine colour pick lands here, in ranking — not in candidate building.
106	    // It reorders the shortlist toward the requested families and is dropped
107	    // silently when the closet cannot honour it.
108	    const top = rankTopN(combos, { aesthetic, band, lean: input.lean }, 20);
109	
110	    const { picks } = await rerank({
111	      combos: top.map((t) =>
112	        t.items.map((ci) => {
113	          const it = byId.get(ci.id)!;
114	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
115	        }),
116	      ),
117	      aesthetic,
118	      occasion: input.occasion,
119	      weatherLabel: f.condition,
120	      tempC: f.tempC,
121	    });
122	
123	    const paths = Array.from(
124	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
125	    );
126	    const signed = await signItemImages(paths);
127	
128	    const looks: Look[] = picks.map((p) => {
129	      const combo = top[p.combo_index]?.items ?? top[0].items;
130	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
131	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
132	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
133	        itemId: d.id,
134	        category: d.category,
135	        subcategory: d.subcategory ?? null,
136	        brand: d.brand ?? null,
137	        name: d.name ?? null,
138	        colors: d.colors ?? [],
139	        cutoutUrl: signed.get(displayPath(d)) ?? "",
140	        slot: slots[idx],
141	      }));
142	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
143	    });
144	
145	    return { status: "ok", weather, looks };
146	  } catch (e) {
147	    console.error("[generate] failed:", e);
148	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
149	  }
150	}
151	
152	/**
153	 * The single write path for a user's location. `generate` stays read-only.
154	 * Called by the client after a successful generate for a location the user
155	 * actually supplied (geolocation or city search) — never for the profile or
156	 * default fallback, where there is nothing new to write.
157	 */
158	export async function saveLocation(input: unknown): Promise<void> {
159	  const d = LocationInputSchema.parse(input);
160	
161	  const supabase = await createClient();
162	  const {
163	    data: { user },
164	  } = await supabase.auth.getUser();
165	  if (!user) return;
166	
167	  await supabase
168	    .from("profiles")
169	    .update({
170	      location_lat: roundCoord(d.lat),
171	      location_lon: roundCoord(d.lon),
172	      location_label: d.label,
173	      location_source: d.source,
174	      location_timezone: d.timezone,
175	      location_updated_at: new Date().toISOString(),
176	    })
177	    .eq("id", user.id);
178	}
